SELECT CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END AS event_cohort, page, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values, MAX(duration_sec) AS max_duration_sec FROM web_events WHERE event_time < '2025-02-03' AND TO_DATE(event_time) < '2025-07-26' GROUP BY event_cohort, page HAVING MAX(duration_sec) >= 260 ORDER BY max_duration_sec DESC
